#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BankResult {
    Ok,
    /// A deposit's credit above `BANK0-RL-01`.
    BalanceLimit,
    InsufficientBalance,
    /// The main backpack's coins cannot pay a deposit.
    InsufficientCoins,
    /// A deposit's change or a withdrawal's coins do not fit the main backpack.
    NoRoom,
    JuniorAccount,
    UnknownRecipient,
    /// A junior recipient, or a credit above `BANK0-RL-01` on the recipient's balance.
    RecipientCannotReceiveTransfers,
    SameAccount,
}
impl BankResult {
    pub fn code(self) -> i16 {
        match self {
            Self::Ok => 0,
            Self::BalanceLimit => 1,
            Self::InsufficientBalance => 2,
            Self::InsufficientCoins => 3,
            Self::NoRoom => 4,
            Self::JuniorAccount => 5,
            Self::UnknownRecipient => 6,
            Self::RecipientCannotReceiveTransfers => 7,
            Self::SameAccount => 8,
        }
    }

    pub fn from_code(code: i16) -> Option<Self> {
        [
            Self::Ok,
            Self::BalanceLimit,
            Self::InsufficientBalance,
            Self::InsufficientCoins,
            Self::NoRoom,
            Self::JuniorAccount,
            Self::UnknownRecipient,
            Self::RecipientCannotReceiveTransfers,
            Self::SameAccount,
        ]
        .into_iter()
        .find(|result| result.code() == code)
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BankOperationKind {
    Deposit,
    Withdraw,
    Transfer,
}
impl BankOperationKind {
    fn code(self) -> i16 {
        match self {
            Self::Deposit => 1,
            Self::Withdraw => 2,
            Self::Transfer => 3,
        }
    }

    fn from_code(code: i16) -> Option<Self> {
        match code {
            1 => Some(Self::Deposit),
            2 => Some(Self::Withdraw),
            3 => Some(Self::Transfer),
            _ => None,
        }
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BankLedgerKind {
    Deposit,
    Withdraw,
    TransferOut,
    TransferIn,
}
impl BankLedgerKind {
    fn code(self) -> u32 {
        match self {
            Self::Deposit => audit::LEDGER_DEPOSIT,
            Self::Withdraw => audit::LEDGER_WITHDRAW,
            Self::TransferOut => audit::LEDGER_TRANSFER_OUT,
            Self::TransferIn => audit::LEDGER_TRANSFER_IN,
        }
    }

    fn from_code(code: i16) -> Option<Self> {
        [
            Self::Deposit,
            Self::Withdraw,
            Self::TransferOut,
            Self::TransferIn,
        ]
        .into_iter()
        .find(|kind| i64::from(kind.code()) == i64::from(code))
    }
}

mod audit {
pub const LEDGER_DEPOSIT: u32 = 1;
pub const LEDGER_WITHDRAW: u32 = 2;
pub const LEDGER_TRANSFER_OUT: u32 = 3;
pub const LEDGER_TRANSFER_IN: u32 = 4;
}
#[test]
fn stored_codes_round_trip() {
        for code in 0..=8 {
            assert_eq!(
                BankResult::from_code(code).map(BankResult::code),
                Some(code)
            );
        }
        assert_eq!(BankResult::from_code(9), None);
        for code in 1..=3 {
            assert_eq!(
                BankOperationKind::from_code(code).map(BankOperationKind::code),
                Some(code)
            );
        }
        for code in 1..=4_i16 {
            assert_eq!(
                BankLedgerKind::from_code(code).map(|kind| i16::try_from(kind.code()).unwrap()),
                Some(code)
            );
        }
    }
#[test]
fn stored_codes_match_migration_0071() {
        // Persisted meanings from 0071_account_bank.sql, independent of the codec.
        for (result, code) in [
            (BankResult::Ok, 0),
            (BankResult::BalanceLimit, 1),
            (BankResult::InsufficientBalance, 2),
            (BankResult::InsufficientCoins, 3),
            (BankResult::NoRoom, 4),
            (BankResult::JuniorAccount, 5),
            (BankResult::UnknownRecipient, 6),
            (BankResult::RecipientCannotReceiveTransfers, 7),
            (BankResult::SameAccount, 8),
        ] {
            assert_eq!(result.code(), code, "{result:?}");
            assert_eq!(BankResult::from_code(code), Some(result));
        }
        for code in [i16::MIN, -1, 9, i16::MAX] {
            assert_eq!(BankResult::from_code(code), None);
        }
        for (kind, code) in [
            (BankOperationKind::Deposit, 1),
            (BankOperationKind::Withdraw, 2),
            (BankOperationKind::Transfer, 3),
        ] {
            assert_eq!(kind.code(), code, "{kind:?}");
            assert_eq!(BankOperationKind::from_code(code), Some(kind));
        }
        for code in [i16::MIN, -1, 0, 4, i16::MAX] {
            assert_eq!(BankOperationKind::from_code(code), None);
        }
        for (kind, code) in [
            (BankLedgerKind::Deposit, 1),
            (BankLedgerKind::Withdraw, 2),
            (BankLedgerKind::TransferOut, 3),
            (BankLedgerKind::TransferIn, 4),
        ] {
            assert_eq!(i16::try_from(kind.code()).unwrap(), code, "{kind:?}");
            assert_eq!(BankLedgerKind::from_code(code), Some(kind));
        }
        for code in [i16::MIN, -1, 0, 5, i16::MAX] {
            assert_eq!(BankLedgerKind::from_code(code), None);
        }
    }

